(()=>{'use strict';let pending=false;function compact(){pending=false;const root=document.querySelector('#main-content');if(!root||document.documentElement.dataset.patiView!=='home')return;const story=root.querySelector(':scope > .stories-section');if(!story)return;for(const el of Array.from(root.children)){if(el===story)break;if(el.classList.contains('pati-home-feed-tabs'))continue;if(el.matches('script,style,[hidden]'))continue;const hasContent=!!el.querySelector('img,video,iframe,button,input,a,[role="button"],canvas')||el.textContent.trim().length>0;if(!hasContent&&el.getBoundingClientRect().height>=30)el.classList.add('buchee-empty-feed-space');}}function queue(){if(!pending){pending=true;requestAnimationFrame(compact)}}new MutationObserver(queue).observe(document.documentElement,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',queue);queue()})();